#!/bin/bashset -e# AIT LMS Production Deployment & Sync Script# Run this on your VPS serverecho "🚀 Starting Production Deployment..."# 1. Pull latest codeecho "📥 Pulling latest code from Git..."git pull# 2. Build & restart all containers with production settingsecho "🏗️ Building all images and restarting containers..."docker compose -f docker-compose.yml -f docker-compose.prod.yml downdocker compose -f docker-compose.yml -f docker-compose.prod.yml up -d --build# 3. Wait for services to be healthyecho "⏳ Waiting for services to be ready..."sleep 15# 4. Run migrationsecho "📊 Running Database Migrations..."docker compose exec -T course-service python manage.py migrate --noinput 2>/dev/null || truedocker compose exec -T auth-service python manage.py migrate --noinput 2>/dev/null || truedocker compose exec -T admission-service python manage.py migrate --noinput 2>/dev/null || trueecho "🔹 [1/7] Seeding Teachers..."echo "   Waiting for auth-service to be ready..."until docker compose exec -T auth-service python -c "import urllib.request; urllib.request.urlopen('http://127.0.0.1:8001/health/')" 2>/dev/null; do sleep 2; donedocker compose exec auth-service python seed_data/seed_teachers_from_sheet.pydocker cp auth-service:/app/teacher_mapping.json ./teacher_mapping.jsondocker cp ./teacher_mapping.json course-service:/app/teacher_mapping.jsonecho "🔹 [2/7] Syncing Academic Structure..."docker compose exec course-service python seed_data/import_academic_structure.pydocker cp course-service:/app/specialization_mapping.json ./specialization_mapping.jsondocker cp ./specialization_mapping.json admission-service:/app/specialization_mapping.jsonecho "🔹 [3/7] Seeding Students & Enrollments..."docker compose exec auth-service python seed_data/seed_students_from_master.pydocker cp auth-service:/app/seed_data/master_enrollment_mapping.json ./master_enrollment_mapping.jsondocker cp ./master_enrollment_mapping.json course-service:/app/master_enrollment_mapping.jsondocker cp auth-service:/app/seed_data/enrollment_mapping.json ./enrollment_mapping.jsondocker cp ./enrollment_mapping.json admission-service:/app/seed_data/enrollment_mapping.jsonecho "🔹 [4/7] Creating Course Registrations & Deposits..."docker compose exec course-service python seed_data/ingest_enrollments.pyecho "🔹 [5/7] Seeding Leads from Sheet..."docker compose exec admission-service python seed_data/seed_leads_from_sheet.pyecho "🔹 [6/7] Syncing Enrollment Lifecycles..."docker compose exec course-service python manage.py sync_enrollment_lifecycleecho "🔹 [7/7] Updating Scheduled Class Statuses..."docker compose exec course-service python seed_data/sync_class_statuses.pyecho "✅ Deployment & Sync Finished Successfully!"echo "🌐 Check your site at: https://lms.iak.ngo"